// ---------- shared helpers ----------
const TZ = 'Asia/Kolkata';
const pad = n => String(n).padStart(2, '0');
const ymd = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const pretty = d => `${pad(d.getDate())} ${MON[d.getMonth()]} ${d.getFullYear()}`;
const todayLocal = () => { const t = $now.setZone(TZ); return new Date(t.year, t.month - 1, t.day); };
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') { const d = new Date(Math.round((v - 25569) * 86400000)); return new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()); }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
  m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/); // DD/MM/YYYY (Indian format)
  if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
  const d = new Date(s);
  return isNaN(d) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate());
}
const splitList = v => String(v ?? '').split(';').map(s => s.trim()).filter(Boolean);
const digits = v => String(v ?? '').replace(/\D/g, '');
const last10 = v => digits(v).slice(-10);
const yes = v => /^(y|yes|true|1)$/i.test(String(v ?? '').trim());
const CLOSED = ['filed', 'not applicable', 'na'];
const isOpen = r => r.task_id && !CLOSED.includes(String(r.status || '').trim().toLowerCase());
const daysBetween = (a, b) => Math.round((b - a) / 86400000);
function renderTask(t) {
  const req = splitList(t.docs_required), rec = splitList(t.docs_received);
  const due = parseDate(t.due_date);
  const lines = [`📋 *${t.form}* – ${t.period}${due ? ` (due ${pretty(due)})` : ''}`];
  for (const d of req) lines.push(`${rec.includes(d) ? '✅' : '⬜'} ${d}`);
