}
// ------------------------------------

// Generates compliance tasks due in the next LOOKAHEAD_DAYS for every active client.
// Due-date rules are the standard statutory dates — adjust if CBIC/CBDT/MCA extends them.
const LOOKAHEAD_DAYS = 60;

const DOCS = {
  'GSTR-1': ['Sales Register', 'Credit/Debit Notes', 'E-way Bill / E-invoice Summary'],
  'GSTR-3B': ['Purchase Register', 'Expense Bills', 'Bank Statement'],
  'GSTR-1 (QRMP)': ['Sales Register (Quarter)', 'Credit/Debit Notes'],
  'GSTR-3B (QRMP)': ['Purchase Register (Quarter)', 'Expense Bills', 'Bank Statement'],
  'PMT-06': ['Sales & Purchase Summary (Month)'],
  'GSTR-9': ['Annual Sales Summary', 'Annual Purchase Summary', 'Financial Statements'],
  'TDS Challan (281)': ['Vendor Payments with TDS', 'Salary Sheet'],
  'TDS Return (24Q/26Q)': ['TDS Challan Copies', 'Deductee PAN Details', 'Salary Details (24Q)'],
  'AOC-4': ['Audited Financial Statements', "Board's Report", "Auditor's Report"],
  'MGT-7/7A': ['Shareholding Pattern', 'Director Details', 'Board & General Meeting Dates'],
  'DPT-3': ['Loans & Deposits Statement', 'Auditor Certificate'],
  'DIR-3 KYC': ['Director PAN', 'Director Aadhaar', 'Director Mobile & Email'],
  'LLP Form 11': ['Partner Contribution Details', 'Designated Partner Details'],
  'LLP Form 8': ['Statement of Accounts & Solvency', 'Signed Financials'],
  'MSME-1': ['MSME Vendor Outstanding List'],
};

const clients = $('Read Clients1').all().map(i => i.json)
  .filter(c => c.client_id && (c.active === undefined || c.active === '' || yes(c.active)));
const existing = new Set($input.all().map(i => i.json.task_id).filter(Boolean));

const today = todayLocal();
const horizon = new Date(today); horizon.setDate(horizon.getDate() + LOOKAHEAD_DAYS);
const fyLabel = fy => `FY ${fy}-${String(fy + 1).slice(2)}`;
const qLabel = (fy, q) => `Q${q} ${fyLabel(fy)}`;
const fyOf = (y, m) => (m >= 3 ? y : y - 1);
const plus = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };

const out = [];
for (const c of clients) {
  const cands = [];
  const add = (type, form, period, due) => cands.push({ type, form, period, due });
  const gst = String(c.gst_filing || '').trim().toLowerCase();   // monthly | qrmp | none
  const et = String(c.entity_type || '').trim().toLowerCase();   // company | llp | other
  const y0 = today.getFullYear(), m0 = today.getMonth();

  // Monthly / quarterly items
  for (let k = -2; k <= 2; k++) {
    const pd = new Date(y0, m0 + k, 1); const py = pd.getFullYear(), pm = pd.getMonth();
    const nd = new Date(py, pm + 1, 1); const ny = nd.getFullYear(), nm = nd.getMonth();
    const per = `${MON[pm]} ${py}`;
    if (gst === 'monthly') {
      add('GST', 'GSTR-1', per, new Date(ny, nm, 11));
      add('GST', 'GSTR-3B', per, new Date(ny, nm, 20));
    }
    if (gst === 'qrmp') {
      const fy = fyOf(py, pm), q = Math.floor(((pm + 9) % 12) / 3) + 1;
      if ([2, 5, 8, 11].includes(pm)) {
        const day3b = parseInt(c.gst_3b_due_day, 10) || 22; // 22 or 24 depending on state
        add('GST', 'GSTR-1 (QRMP)', qLabel(fy, q), new Date(ny, nm, 13));
        add('GST', 'GSTR-3B (QRMP)', qLabel(fy, q), new Date(ny, nm, day3b));
      } else {
        add('GST', 'PMT-06', per, new Date(ny, nm, 25));
      }
    }
    if (yes(c.tds_applicable)) {
      add('TDS', 'TDS Challan (281)', per, pm === 2 ? new Date(ny, 3, 30) : new Date(ny, nm, 7));
    }
  }

  // Annual items
  for (const fy of [y0 - 2, y0 - 1, y0]) {
    if (yes(c.tds_applicable)) {
      add('TDS', 'TDS Return (24Q/26Q)', qLabel(fy, 1), new Date(fy, 6, 31));
      add('TDS', 'TDS Return (24Q/26Q)', qLabel(fy, 2), new Date(fy, 9, 31));
      add('TDS', 'TDS Return (24Q/26Q)', qLabel(fy, 3), new Date(fy + 1, 0, 31));
      add('TDS', 'TDS Return (24Q/26Q)', qLabel(fy, 4), new Date(fy + 1, 4, 31));
    }
    if ((gst === 'monthly' || gst === 'qrmp') && yes(c.gstr9_applicable)) {
      add('GST', 'GSTR-9', fyLabel(fy), new Date(fy + 1, 11, 31));
    }
    if (yes(c.roc_applicable) && et === 'company') {
      const agmIn = parseDate(c.agm_date);
      const agm = agmIn ? new Date(fy + 1, agmIn.getMonth(), agmIn.getDate()) : new Date(fy + 1, 8, 30);
      add('ROC', 'AOC-4', fyLabel(fy), plus(agm, 30));
      add('ROC', 'MGT-7/7A', fyLabel(fy), plus(agm, 60));
      add('ROC', 'DPT-3', fyLabel(fy), new Date(fy + 1, 5, 30));
      add('ROC', 'DIR-3 KYC', fyLabel(fy), new Date(fy + 1, 8, 30));
    }
    if (yes(c.roc_applicable) && et === 'llp') {
      add('ROC', 'LLP Form 11', fyLabel(fy), new Date(fy + 1, 4, 30));
      add('ROC', 'LLP Form 8', fyLabel(fy), new Date(fy + 1, 9, 30));
    }
    if (yes(c.msme_applicable)) {
      add('ROC', 'MSME-1', `H1 ${fyLabel(fy)}`, new Date(fy, 9, 31));
      add('ROC', 'MSME-1', `H2 ${fyLabel(fy)}`, new Date(fy + 1, 3, 30));
    }
  }

  for (const t of cands) {
    if (t.due < today || t.due > horizon) continue;
    const task_id = `${c.client_id}|${t.form}|${t.period}`;
    if (existing.has(task_id)) continue;
    existing.add(task_id);
    out.push({ json: {
      task_id,
      client_id: String(c.client_id),
      client_name: c.client_name || '',
      whatsapp_number: digits(c.whatsapp_number),
      compliance_type: t.type,
      form: t.form,
      period: t.period,
      due_date: ymd(t.due),
      status: 'Pending',
      docs_required: (DOCS[t.form] || ['Supporting Documents']).join('; '),
      docs_received: '',
      checklist_pct: 0,
      last_reminder_sent: '',
      reminder_count: 0,
    }});
  }
}
return out;

