// Builds ONE WhatsApp message per client covering all tasks that need a nudge today.
const REMIND_DAYS = [7, 3, 1, 0];      // days before due date
const FIRST_NOTICE_WITHIN = 15;        // first reminder as soon as a task is <= 15 days away
const USE_TEMPLATE = true;             // Meta requires an approved template for business-initiated messages
const TEMPLATE_NAME = 'compliance_reminder';
const TEMPLATE_LANG = 'en';

const today = todayLocal();
const todayStr = ymd(today);
const groups = {};

for (const r of $input.all().map(i => i.json)) {
  if (!isOpen(r)) continue;
  if (String(r.status || '').trim().toLowerCase() === 'docs complete') continue;
  const due = parseDate(r.due_date); if (!due) continue;
  const req = splitList(r.docs_required), rec = splitList(r.docs_received);
  const missing = req.filter(d => !rec.includes(d));
  if (!missing.length) continue;
  const lr = parseDate(r.last_reminder_sent);
  if (lr && ymd(lr) === todayStr) continue;
  const left = daysBetween(today, due);
  const count = Number(r.reminder_count || 0);
  const shouldSend = REMIND_DAYS.includes(left) || left < 0 || (count === 0 && left <= FIRST_NOTICE_WITHIN);
  if (!shouldSend) continue;
  const to = digits(r.whatsapp_number); if (!to) continue;
  (groups[to] ||= { to, client_id: r.client_id, client_name: r.client_name, tasks: [] })
    .tasks.push({ ...r, due, left, missing, reminder_count: count });
}

const when = t => t.left > 1 ? `${t.left} days left` : t.left === 1 ? 'due tomorrow'
  : t.left === 0 ? 'due TODAY' : `OVERDUE by ${-t.left} day(s)`;
const clean = s => String(s).replace(/[\n\t]+/g, ' ').replace(/ {4,}/g, '   ').slice(0, 900);

return Object.values(groups).map(g => {
  g.tasks.sort((a, b) => a.due - b.due);
  const summary = g.tasks.map(t => `${t.form} (${t.period}) due ${pretty(t.due)} – ${when(t)}`).join(' | ');
  const pending = g.tasks.map(t => `${t.form}: ${t.missing.join(', ')}`).join(' | ');
  const payload = USE_TEMPLATE
    ? { messaging_product: 'whatsapp', to: g.to, type: 'template',
        template: { name: TEMPLATE_NAME, language: { code: TEMPLATE_LANG },
          components: [{ type: 'body', parameters: [
            { type: 'text', text: clean(g.client_name || 'there') },
            { type: 'text', text: clean(summary) },
            { type: 'text', text: clean(pending) },
          ]}]}}
    : { messaging_product: 'whatsapp', to: g.to, type: 'text',
        text: { body: `Hello ${g.client_name}, a reminder from your CA office:\n\n` +
          g.tasks.map(t => `${renderTask(t)}\n⏰ ${when(t)}`).join('\n\n') +
          `\n\nReply with the files here (PDF / Excel / photo). Reply STATUS anytime to see your checklist.` } };
  return { json: { to: g.to, client_id: g.client_id, payload,
    tasks: g.tasks.map(t => ({ task_id: t.task_id, reminder_count: t.reminder_count })) } };
});

