// Identifies the client from the WhatsApp number and decides what to do with the message.
const j = $('WhatsApp Trigger1').first().json;
const v = Array.isArray(j.messages) ? j
  : (j.entry?.[0]?.changes?.[0]?.value || j.body?.entry?.[0]?.changes?.[0]?.value || {});
const msg = v.messages?.[0];
if (!msg) return [{ json: { route: 'ignore' } }];   // delivery/read status callbacks

const from = digits(msg.from);
const textPayload = body => ({ messaging_product: 'whatsapp', to: from, type: 'text', text: { body } });

const clients = $('Read Clients (Inbound)1').all().map(i => i.json).filter(c => c.client_id);
const client = clients.find(c => last10(c.whatsapp_number) && last10(c.whatsapp_number) === last10(from));
if (!client) {
  return [{ json: { route: 'reply', payload: textPayload(
    "Hello! This number isn't registered with our compliance desk yet. Please contact your CA office to get it linked to your account.") } }];
}

const tasks = $input.all().map(i => i.json)
  .filter(r => isOpen(r) && String(r.client_id) === String(client.client_id))
  .sort((a, b) => (parseDate(a.due_date) || 0) - (parseDate(b.due_date) || 0));
const open_tasks = tasks.map(t => ({
  task_id: t.task_id, form: t.form, period: t.period, due_date: t.due_date,
  docs_required: t.docs_required || '', docs_received: t.docs_received || '',
}));
const missing = [];
for (const t of open_tasks) {
  const rec = splitList(t.docs_received);
  for (const d of splitList(t.docs_required)) if (!rec.includes(d)) missing.push({ task_id: t.task_id, form: t.form, period: t.period, doc: d });
}

if (msg.type === 'document' || msg.type === 'image') {
  const media = msg[msg.type] || {};
  let ext = ((media.mime_type || '').split('/')[1] || 'bin').split(';')[0];
  if (ext === 'jpeg') ext = 'jpg';
  const file_name = media.filename || `${msg.type}_${Date.now()}.${ext}`;
  const caption = media.caption || '';
  const ai_prompt =
`File name: ${file_name}
Caption from client: ${caption || '(none)'}
MIME type: ${media.mime_type || ''}
Today: ${ymd(todayLocal())}

Pending checklist items (task_id :: document):
${missing.map(m => `${m.task_id} :: ${m.doc}`).join('\n') || '(none)'}

Return JSON: {"matches":[{"task_id":"...","doc":"..."}],"reason":"one short sentence"}`;
  return [{ json: {
    route: 'media', to: from, client, open_tasks, missing,
    media_id: media.id, mime_type: media.mime_type || '', file_name, caption,
    drive_file_name: `${client.client_id}_${ymd(todayLocal())}_${file_name}`.replace(/[\\/:*?"<>|]/g, '_'),
