    `\n\nSend any document here (PDF, Excel or photo) and it will be ticked off automatically. ` +
    `A caption like "Aug purchase register" helps file it correctly.`;
  return [{ json: { route: 'reply', payload: textPayload(body) } }];
}

return [{ json: { route: 'reply', payload: textPayload(
  'Please send documents as a PDF, Excel file or photo. Reply STATUS to see your pending checklist.') } }];

