// Validates the AI match, updates the checklist, and prepares reply + log + sheet updates.
const ctx = $('Route Incoming Message1').first().json;
const drive = $('Upload to Client Drive Folder1').first().json || {};
const ai = $input.first().json || {};

let content = ai.message?.content ?? ai.content ?? ai.output ?? ai.text ?? ai.choices?.[0]?.message?.content ?? {};
if (typeof content === 'string') {
  try { content = JSON.parse(content.replace(/```json|```/g, '').trim()); } catch (e) { content = {}; }
}
const rawMatches = Array.isArray(content.matches) ? content.matches : [];
const validKey = new Set(ctx.missing.map(m => `${m.task_id}::${m.doc}`));
const seen = new Set();
const matched = rawMatches.filter(m => {
  const k = `${m.task_id}::${m.doc}`;
  if (!validKey.has(k) || seen.has(k)) return false;
  seen.add(k); return true;
});

const tasks = ctx.open_tasks.map(t => ({ ...t }));
const byId = Object.fromEntries(tasks.map(t => [t.task_id, t]));
for (const m of matched) {
  const t = byId[m.task_id];
  const rec = splitList(t.docs_received);
  if (!rec.includes(m.doc)) rec.push(m.doc);
  t.docs_received = rec.join('; ');
}

const updates = [];
for (const id of new Set(matched.map(m => m.task_id))) {
  const t = byId[id];
  const req = splitList(t.docs_required), rec = splitList(t.docs_received);
  const pct = req.length ? Math.round(req.filter(d => rec.includes(d)).length / req.length * 100) : 100;
  t.status = pct >= 100 ? 'Docs Complete' : 'Docs Partial';
  updates.push({ task_id: id, docs_received: t.docs_received, checklist_pct: pct, status: t.status });
}

const driveLink = drive.id ? `https://drive.google.com/file/d/${drive.id}/view` : '';
let body;
if (matched.length) {
  const affected = tasks.filter(t => updates.some(u => u.task_id === t.task_id));
  body = `✅ Received *${ctx.file_name}* – ticked off:\n` +
    matched.map(m => `• ${m.doc} (${byId[m.task_id].form} – ${byId[m.task_id].period})`).join('\n') +
    `\n\n` + affected.map(t => renderTask(t) + (t.status === 'Docs Complete' ? '\n🎉 All documents received – our team will take it from here.' : '')).join('\n\n');
} else {
  body = `📥 Received *${ctx.file_name}* and saved it to your folder. ` +
    `I couldn't match it to a pending checklist item automatically, so our team will review it.\n` +
    `Tip: add a caption like "Aug 2026 purchase register".` +
    (tasks.length ? `\n\nStill pending:\n\n${tasks.map(renderTask).join('\n\n')}` : '');
}

return [{ json: {
  payload: { messaging_product: 'whatsapp', to: ctx.to, type: 'text', text: { body: body.slice(0, 4000) } },
  updates,
  log_row: {
    timestamp: $now.setZone(TZ).toFormat('yyyy-LL-dd HH:mm:ss'),
    client_id: String(ctx.client.client_id),
    client_name: ctx.client.client_name || '',
    file_name: ctx.file_name,
    drive_file_id: drive.id || '',
    drive_link: driveLink,
    matched_items: matched.map(m => `${m.task_id} :: ${m.doc}`).join('; ') || 'UNMATCHED – review',
    ai_reason: String(content.reason || ''),
    whatsapp_media_id: ctx.media_id || '',
  },
} }];
